schemas.content:
section fltCpnHist: BloombergData
{
  filter: 'DATA=FLT_CPN_HIST';

  Record
  {
    SECURITY: STRING;
    ERROR_COUNT: INTEGER;
    FIELD_COUNT: INTEGER;
    ID_BB_UNIQUE: STRING;
    ID_BB_COMPANY: INTEGER;
    ID_BB_SECURITY: INTEGER;
    ID_BB_GLOBAL: STRING;
    ID_ISIN: STRING(optional);
    ID_BB_SEC_NUM_DES: STRING(optional);
    FEED_SOURCE: STRING(optional);
    FLT_CPN_HIST_DT: DATE;
    FLT_CPN_HIST_RT: DECIMAL(optional);
  }
}
section fltCpnHistMetaRecord: BloombergMetadata
{
  Record
  {
    PROGRAMNAME  : STRING;
    DATEFORMAT   : STRING;
    REGION       : STRING;
    TYPE         : STRING;
    DATARECORDS  : INTEGER;
    TIMESTARTED  : DATETIME(format='EEE MMM d HH:mm:ss zz yyyy');
    TIMEFINISHED : DATETIME(format='EEE MMM d HH:mm:ss zz yyyy');
  }
}
section callSchedule: BloombergData
{
  filter: 'DATA=CALL_SCHEDULE';

  Record
  {
    SECURITY: STRING;
    ERROR_COUNT: INTEGER;
    FIELD_COUNT: INTEGER;
    ID_BB_UNIQUE: STRING;
    ID_BB_COMPANY: INTEGER;
    ID_BB_SECURITY: INTEGER;
    ID_BB_GLOBAL: STRING;
    ID_ISIN: STRING(optional);
    ID_BB_SEC_NUM_DES: STRING(optional);
    FEED_SOURCE: STRING(optional);
    CALL_SCHEDULE_DT: DATE;
    CALL_SCHEDULE_PCT: DECIMAL;
  }
}
section callScheduleMetaRecord: BloombergMetadata
{
  Record
  {
    PROGRAMNAME  : STRING;
    DATEFORMAT   : STRING;
    REGION       : STRING;
    TYPE         : STRING;
    DATARECORDS  : INTEGER;
    TIMESTARTED  : DATETIME(format='EEE MMM d HH:mm:ss zz yyyy');
    TIMEFINISHED : DATETIME(format='EEE MMM d HH:mm:ss zz yyyy');
  }
}
